    setPair(D, {9422,60102}, "Finalizador que expõe o alvo durante {{1}}, reduzindo a armadura por ponto de combo:\n1 ponto: {{2}} armadura\n2 pontos: {{3}} armadura\n3 pontos: {{4}} armadura\n4 pontos: {{5}} armadura\n5 pontos: {{6}} armadura.")
    setPair(D, {9564,100715}, "Encanta permanentemente uma capa para aumentar a Agilidade em {{1}}.")
    setPair(D, {9616,60291}, "Aumenta a duração do efeito de sua habilidade Desorientar em 1.5 s e reduz a recarga em {{1}} s.")
