    local D, T = A.DescPairs, A.TipPairs
    local function setPair(P, indices, text)
        if not P then return end
        for i = 1, #indices do
            local pair = P[indices[i]]
            if type(pair) == "table" and type(pair[1]) == "string" then pair[2] = text end
        end
    end

