    setOne(D, 52324, [[\	adiciona permanentemente 12 poder mágico a um colar.

só pode usar em itens que exijam nível 65 a 70.]])
    setOne(D, 52325, [[\	adiciona permanentemente 16 poder mágico a um colar.

só pode usar em itens que exijam nível 65 a 70.]])
    setOne(D, 52326, [[\	adiciona permanentemente 8 vigor e 8 resistência ao dano crítico a um colar.

só pode usar em itens que exijam nível 65 a 70.]])
    setOne(D, 52327, [[\	adiciona permanentemente 12 vigor e 12 resistência ao dano crítico a um colar.

